#!/usr/bin/env python3
import hashlib,json,os
from pathlib import Path
H=Path(__file__).resolve().parent;M=H/'maintenance';OUT=M/'closure-composite-final-install-receipt.json'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def load(n):p=M/n;return p,json.load(open(p))
v4p,v4=load('closure-baseline-final-install-gate-20260716-v4.json');gp,g=load('closure-final-changed-92-gate-v6.json');ip,inv=load('closure-staging-worksheet-inventory-final.json');pp,par=load('closure-baseline-staging-worksheet-parity-20260716.json');dp,diff=load('closure-final-depth-regression-diff.json')
old={x['id']:x['sha256'] for x in v4['entries']};changed=[r for r in inv['rows'] if r['entrySha256']!=old.get(r['id'])];unchanged=[r for r in inv['rows'] if r['entrySha256']==old.get(r['id'])]
clean=(g['exactKwic']['failureCount']==0 and g['attribution']['payload']['hardFailures']==0 and g['attributionPackets']['hardPass'] and g['attributionPackets']['turnProofMissing']==0 and g['attributionPackets']['occurrenceIdentityFailures']==0 and g['countClaims']['payload']['mismatchCount']==0 and g['workSourceValidation']['payload']['hardFailures']==0 and g['corpusBaseline']['payload']['hardFailures']==0 and g['frozenHistoricalTerms']['payload']['hardFailures']==0 and not g['forbiddenEnglish'] and g['publicFeedback']['payload']['flagged']==0)
authorized=(len(unchanged)==1112 and len(changed)==92 and clean and diff['hardPass'] and diff['newOrWorsened']==0 and inv['hardPass'] and inv['entries']==1204 and par['unresolved']==0 and par['currentParity']==1204)
o={'schemaVersion':'closure-composite-final-install.v1','installAuthorized':authorized,'entryCount':1204,'unchangedAcceptedV4':{'count':len(unchanged),'gate':str(v4p.relative_to(H)),'gateSha256':sha(v4p),'entryHashes':[{'id':r['id'],'sha256':r['entrySha256']} for r in unchanged]},'changedFreshGate':{'count':len(changed),'gate':str(gp.relative_to(H)),'gateSha256':sha(gp),'entryHashes':[{'id':r['id'],'sha256':r['entrySha256']} for r in changed],'mechanicalHardPass':clean,'depthSenseComplete':False,'residualDepthDebtCarriedForward':True},'depthRegression':{'path':str(dp.relative_to(H)),'sha256':sha(dp),'newOrWorsened':diff['newOrWorsened'],'hardPass':diff['hardPass']},'worksheetInventory':{'path':str(ip.relative_to(H)),'sha256':sha(ip),'pairs':inv['entryWorksheetPairs'],'readerPollutionCount':inv['readerPollutionCount'],'hardPass':inv['hardPass']},'worksheetParity':{'path':str(pp.relative_to(H)),'sha256':sha(pp),'currentParity':par['currentParity'],'unresolved':par['unresolved']},'installScope':'Atomically promote all 1,204 staged entry products and canonical worksheets to fresh-build; publish all 1,204 entry products through terms/STATUS=done and the fresh merge.','entryHashes':[{'id':r['id'],'entrySha256':r['entrySha256'],'worksheetSha256':r['worksheetSha256']} for r in inv['rows']]}
t=OUT.with_suffix('.tmp');t.write_text(json.dumps(o,ensure_ascii=False,indent=2)+'\n');os.replace(t,OUT);print(json.dumps({'installAuthorized':authorized,'unchanged':len(unchanged),'changed':len(changed),'sha256':sha(OUT)}));raise SystemExit(0 if authorized else 1)
